package cn.mop.persistence;
import cn.mop.domain.contact.CustomerContact.QuietWindow;
import cn.mop.domain.notification.OwnNotificationPreferenceDraft;
import cn.mop.domain.notification.OwnNotificationPreferenceDraft.LevelPreference;
import cn.mop.domain.notification.DeliveryReceiptState.Channel;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real restricted PostgreSQL structural checks. Every inserted test preference is rolled back; no receiver or dispatch. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresNotificationPreferenceSchemaIntegrationTest {
    static HikariDataSource pool;
    String tenant;
    Connection c;String actor,other,foreign;long permission;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(2);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);}
    @BeforeEach void begin()throws Exception{c=pool.getConnection();c.setAutoCommit(false);selectUnusedActualMembership();}
    void selectUnusedActualMembership()throws SQLException{
        // Never clear a persisted person's singleton preference to make a schema test pass.
        try(var s=c.createStatement();var r=s.executeQuery("SELECT m.tenant_id::text,m.user_id::text,m.permission_version FROM public.mop_membership m JOIN public.mop_user u ON u.id=m.user_id WHERE m.active AND u.active AND NOT EXISTS(SELECT 1 FROM public.mop_notification_preference_draft p WHERE p.tenant_id=m.tenant_id AND p.owner_id=m.user_id) ORDER BY m.tenant_id,m.user_id LIMIT 1 FOR UPDATE OF m")){
            assertTrue(r.next(),"Schema probes require an unused existing test membership; preserve all existing preferences");tenant=r.getString(1);actor=r.getString(2);permission=r.getLong(3);
        }
        other=scalar("SELECT user_id::text FROM public.mop_membership WHERE tenant_id='"+tenant+"' AND user_id<>'"+actor+"' AND active ORDER BY user_id LIMIT 1");
        foreign=scalar("SELECT user_id::text FROM public.mop_membership m WHERE tenant_id<>'"+tenant+"' AND NOT EXISTS(SELECT 1 FROM public.mop_membership own WHERE own.tenant_id='"+tenant+"' AND own.user_id=m.user_id) ORDER BY user_id LIMIT 1");
    }
    @AfterEach void rollback()throws Exception{if(c!=null){c.rollback();c.close();}}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    void sql(String q)throws SQLException{try(var s=c.createStatement()){s.execute(q);}}
    String scalar(String q)throws SQLException{try(var s=c.createStatement();var r=s.executeQuery(q)){assertTrue(r.next());return r.getString(1);}}
    @FunctionalInterface interface Action{void run()throws Exception;}
    void rejected(String state,Action action)throws Exception{var save=c.setSavepoint();var e=assertThrows(SQLException.class,action::run);assertEquals(state,e.getSQLState());c.rollback(save);c.releaseSavepoint(save);}
    void validate()throws SQLException{sql("SET CONSTRAINTS ALL IMMEDIATE");sql("SET CONSTRAINTS ALL DEFERRED");}
    OwnNotificationPreferenceDraft definition(LevelPreference level,List<Channel> channels,QuietWindow quiet){return new OwnNotificationPreferenceDraft(UUID.fromString(tenant),UUID.fromString(actor),level,channels,quiet);}
    OwnNotificationPreferenceDraft standard(){return definition(LevelPreference.P1_P2,List.of(Channel.VOICE,Channel.EMAIL),new QuietWindow(true,LocalTime.of(22,0),LocalTime.of(7,0)));}
    String head()throws SQLException{String id=UUID.randomUUID().toString();sql("INSERT INTO public.mop_notification_preference_draft(id,tenant_id,owner_id) VALUES ('"+id+"','"+tenant+"','"+actor+"')");return id;}
    void revision(String id,int version,OwnNotificationPreferenceDraft d,Map<String,Object> overrides)throws SQLException{
        var values=new LinkedHashMap<String,Object>();values.put("tenant_id",UUID.fromString(tenant));values.put("preference_id",UUID.fromString(id));values.put("owner_id",UUID.fromString(actor));values.put("version",version);values.put("previous_version",version==1?null:version-1);values.put("recorded_by",UUID.fromString(actor));values.put("recorded_permission_version",permission);values.put("recorded_at",OffsetDateTime.parse(scalar("SELECT updated_at::text FROM public.mop_notification_preference_draft WHERE id='"+id+"'").replace(' ','T')));values.put("action",version==1?"CREATE":"UPDATE");values.put("requested_level",d.requestedLevel()==null?null:d.requestedLevel().name());values.put("requested_channels",d.requestedChannels()==null?null:c.createArrayOf("text",d.requestedChannels().stream().map(Enum::name).toArray(String[]::new)));var w=d.requestedQuietWindow();values.put("quiet_window_supplied",w!=null);values.put("quiet_enabled",w==null?null:w.enabled());values.put("quiet_start",w==null||w.start()==null?null:w.start().toString());values.put("quiet_end",w==null||w.end()==null?null:w.end().toString());values.put("content_sha256",d.fingerprint());values.putAll(overrides);
        String q="INSERT INTO public.mop_notification_preference_revision("+String.join(",",values.keySet())+") VALUES ("+String.join(",",Collections.nCopies(values.size(),"?"))+")";try(var s=c.prepareStatement(q)){int n=0;for(Object v:values.values())s.setObject(++n,v);s.executeUpdate();}
    }
    String create(OwnNotificationPreferenceDraft d)throws SQLException{String id=head();revision(id,1,d,Map.of());validate();return id;}
    String create()throws SQLException{return create(standard());}
    void advance(String id,int version,OwnNotificationPreferenceDraft d)throws SQLException{sql("UPDATE public.mop_notification_preference_draft SET version="+version+",updated_at=clock_timestamp()::timestamptz(3) WHERE id='"+id+"'");revision(id,version,d,Map.of());validate();}
    @Test void structureAclAndFixedFunctionBodiesMatchReviewedResource()throws Exception{NotificationPreferenceSchemaVerifier.resource();NotificationPreferenceSchemaVerifier.verify(c);}
    @Test void javaFingerprintMatchesDatabaseAndDraftDoesNotActivate()throws Exception{String id=create();assertEquals(standard().fingerprint(),scalar("SELECT content_sha256 FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"'"));assertEquals("t",scalar("SELECT NOT effective AND effective_level IS NULL AND effective_channels IS NULL AND effective_quiet_window IS NULL AND verified_receiver_id IS NULL AND delivery_decision IS NULL AND NOT notification_dispatched FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"'"));}
    @Test void onlyOneCurrentDraftPerTenantOwner()throws Exception{create();rejected("23505",()->head());}
    @Test void missingCurrentRevisionCannotCommit()throws Exception{rejected("23503",()->{head();validate();});}
    @Test void badFingerprintFailsAtDeferredBoundary()throws Exception{rejected("23514",()->{String id=head();revision(id,1,standard(),Map.of("content_sha256","0".repeat(64)));validate();});}
    @Test void orderedChannelsAreCanonicalNotRoutingPriority()throws Exception{String id=create();assertEquals("{EMAIL,VOICE}",scalar("SELECT requested_channels::text FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"'"));}
    @Test void unknownAndExplicitEmptyChannelsRemainDifferent()throws Exception{String id=create(definition(null,null,null));String first=scalar("SELECT content_sha256 FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"' AND version=1");assertNull(scalar("SELECT requested_channels::text FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"' AND version=1"));advance(id,2,definition(null,List.of(),null));assertEquals("{}",scalar("SELECT requested_channels::text FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"' AND version=2"));assertNotEquals(first,scalar("SELECT content_sha256 FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"' AND version=2"));}
    @Test void unconfiguredUnknownAndDisabledWindowRemainDistinct()throws Exception{String id=create(definition(null,null,null));advance(id,2,definition(null,null,new QuietWindow(null,null,null)));advance(id,3,definition(null,null,new QuietWindow(false,null,null)));assertEquals("3",scalar("SELECT count(DISTINCT content_sha256)::text FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"'"));assertEquals("f,t,t",scalar("SELECT string_agg(quiet_window_supplied::text,',' ORDER BY version) FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"'" ).replace("false","f").replace("true","t"));}
    @Test void duplicateAndNonCanonicalChannelOrderFail()throws Exception{for(String[] channels:new String[][]{{"EMAIL","EMAIL"},{"VOICE","EMAIL"}})rejected("23514",()->{String id=head();revision(id,1,standard(),Map.of("requested_channels",c.createArrayOf("text",channels)));validate();});}
    @Test void unknownAndNullChannelCodesFailImmediately()throws Exception{for(String[] channels:new String[][]{{"UNKNOWN"},{"EMAIL",null}})rejected("23514",()->{String id=head();revision(id,1,standard(),Map.of("requested_channels",c.createArrayOf("text",channels)));});}
    @Test void invalidMinuteWindowsAndHiddenTimesAreRejected()throws Exception{for(var overrides:List.of(Map.<String,Object>of("quiet_start","24:00"),Map.<String,Object>of("quiet_end","22:00"),Map.<String,Object>of("quiet_enabled",false),Map.<String,Object>of("quiet_window_supplied",false)))rejected("23514",()->{String id=head();revision(id,1,standard(),overrides);});}
    @Test void unknownPriorityAndForgedEffectiveFlagsFail()throws Exception{for(var overrides:List.of(Map.<String,Object>of("requested_level","P0"),Map.<String,Object>of("effective",true),Map.<String,Object>of("effective_level","P1_ONLY"),Map.<String,Object>of("configuration_status","ACTIVE"),Map.<String,Object>of("delivery_decision",true),Map.<String,Object>of("notification_dispatched",true),Map.<String,Object>of("verified_receiver_id",UUID.fromString(actor)),Map.<String,Object>of("receiver_binding_status","VERIFIED")))rejected("23514",()->{String id=head();revision(id,1,standard(),overrides);});}
    @Test void foreignOwnerCannotCreateHeadInThisTenant()throws Exception{rejected("23503",()->sql("INSERT INTO public.mop_notification_preference_draft(id,tenant_id,owner_id) VALUES ('"+UUID.randomUUID()+"','"+tenant+"','"+foreign+"')"));}
    @Test void anotherMemberCannotBeRecordedAsTheOwner()throws Exception{rejected("23514",()->{String id=head();revision(id,1,standard(),Map.of("recorded_by",UUID.fromString(other)));});rejected("23503",()->{String id=head();revision(id,1,standard(),Map.of("owner_id",UUID.fromString(other),"recorded_by",UUID.fromString(other)));});}
    @Test void currentHeadCannotSkipOrRepeatVersions()throws Exception{String id=create();for(int version:new int[]{0,1,3})rejected("23514",()->sql("UPDATE public.mop_notification_preference_draft SET version="+version+" WHERE id='"+id+"'"));}
    @Test void futureRevisionWithoutHeadAdvanceFails()throws Exception{String id=create();rejected("23514",()->{revision(id,2,standard(),Map.of());validate();});}
    @Test void advancingHeadWithoutNewRevisionFails()throws Exception{String id=create();rejected("23503",()->{sql("UPDATE public.mop_notification_preference_draft SET version=2 WHERE id='"+id+"'");validate();});}
    @Test void updatePreservesOriginalRevisionAndOwnership()throws Exception{String id=create();String old=scalar("SELECT to_jsonb(r)::text FROM public.mop_notification_preference_revision r WHERE preference_id='"+id+"' AND version=1");advance(id,2,definition(LevelPreference.ALL,List.of(),new QuietWindow(false,null,null)));assertEquals(old,scalar("SELECT to_jsonb(r)::text FROM public.mop_notification_preference_revision r WHERE preference_id='"+id+"' AND version=1"));assertEquals(actor,scalar("SELECT owner_id::text FROM public.mop_notification_preference_draft WHERE id='"+id+"'"));}
    @Test void runtimeCannotRewriteOrDeleteHistoryAndOwnerColumns()throws Exception{String id=create();for(String q:List.of("UPDATE public.mop_notification_preference_revision SET effective=true WHERE preference_id='"+id+"'","DELETE FROM public.mop_notification_preference_revision WHERE preference_id='"+id+"'","DELETE FROM public.mop_notification_preference_draft WHERE id='"+id+"'","UPDATE public.mop_notification_preference_draft SET owner_id='"+other+"' WHERE id='"+id+"'","TRUNCATE public.mop_notification_preference_revision"))rejected("42501",()->sql(q));}
    @Test void futureHeadAndRevisionObservationCannotBeInserted()throws Exception{rejected("23514",()->sql("INSERT INTO public.mop_notification_preference_draft(id,tenant_id,owner_id,created_at,updated_at) VALUES ('"+UUID.randomUUID()+"','"+tenant+"','"+actor+"',clock_timestamp()+interval '1 day',clock_timestamp()+interval '1 day')"));rejected("23514",()->{String id=head();revision(id,1,standard(),Map.of("recorded_at",OffsetDateTime.now(ZoneOffset.UTC).plusDays(1)));});}
    @Test void wrongCreationTransactionMarkerIsRejected()throws Exception{rejected("23514",()->{String id=head();var xid=new org.postgresql.util.PGobject();xid.setType("xid8");xid.setValue("0");revision(id,1,standard(),Map.of("creation_xid",xid));});}
    @Test void schemaProbeSelectionPreservesAlreadyStoredOwnerPreferences()throws Exception{
        String id=create(),priorOwner=actor,priorTenant=tenant;String before=scalar("SELECT to_jsonb(r)::text FROM public.mop_notification_preference_revision r WHERE preference_id='"+id+"'");selectUnusedActualMembership();assertFalse(priorOwner.equals(actor)&&priorTenant.equals(tenant));assertEquals(before,scalar("SELECT to_jsonb(r)::text FROM public.mop_notification_preference_revision r WHERE preference_id='"+id+"'"));
    }
}
